-- 0042 · THƯ VIỆN QUY TRÌNH CHUẨN THEO BỘ GỐC (Quyển 3 §15): 8 chuỗi L1 · 66 quy trình L2 · ~420 SOP L3 (mỗi L3 = 1 bước quy trình + 1 mục thư viện SOP) · 12 điểm giao nhận SLA
-- Mã L2: SOP-[BỘ PHẬN]-[NN]; SOP L3: SOP-[BỘ PHẬN]-[NN].[k]. Bộ phận: BO GA DE RAS TOM TT SH NAM CB KD RS HC CN AT
alter table sops add column if not exists version int default 1, add column if not exists std_clauses text[] default '{}', add column if not exists owner_role text, add column if not exists l2_code text, add column if not exists l3_no int, add column if not exists tools text, add column if not exists frequency text, add column if not exists pass_criteria text, add column if not exists evidence text, add column if not exists safety text, add column if not exists video_url text, add column if not exists published_at timestamptz, add column if not exists published_by text, add column if not exists review_due date, add column if not exists ccp bool default false, add column if not exists ccp_limit text, add column if not exists ccp_action text;
alter table processes add column if not exists l1_chain text, add column if not exists organ text, add column if not exists sop_count int;
create temp table _l2(code text, organ text, dept text, l1 text, name text, n int, obj text, ui text, tools text, recv text, give text, evidence text, sops text[]);
