-- 1) Quy trình L2 → processes
insert into processes(code,dept_code,name,kind,object_type,trigger_text,inputs,outputs,sla,owner_role,kpi,tables,ui_path,coverage,status,l1_chain,organ,sop_count,description,position)
select code, dept, name, 'CORE', obj, 'Theo lịch/ca hoặc sự kiện', jsonb_build_array(jsonb_build_object('from','*','what',recv,'via','xem bảng')), jsonb_build_array(jsonb_build_object('to','*','what',give,'via','xem bảng')), 'Theo SOP', 'team_lead', evidence, '{}', ui, 'DA_CO', 'BAN_HANH', l1, organ, n, 'Quy trình chuẩn bộ gốc (Quyển 3 §15) · '||n||' SOP L3', 200 + row_number() over () from _l2
on conflict (code) do update set name=excluded.name, dept_code=excluded.dept_code, l1_chain=excluded.l1_chain, organ=excluded.organ, sop_count=excluded.sop_count, inputs=excluded.inputs, outputs=excluded.outputs, kpi=excluded.kpi, ui_path=excluded.ui_path, description=excluded.description;
-- 2) SOP L3 → process_steps + thư viện sops
insert into process_steps(process_code,step_no,name,actor_role,dept_code,action,system_where,control,form_table,sla_hours,tools,output)
select l.code, s.k, s.name, case when l.dept in ('KTCN','TT','SH','D5','CCU','DL') then 'worker' else 'team_lead' end, l.dept, s.name, l.ui, 'Chuẩn ĐẠT theo SOP '||l.code||'.'||s.k, null, 24, string_to_array(l.tools, ', '), 'Bằng chứng: '||l.evidence
from _l2 l, unnest(l.sops) with ordinality as s(name, k)
on conflict (process_code, step_no) do update set name=excluded.name, dept_code=excluded.dept_code, action=excluded.action, tools=excluded.tools, output=excluded.output;
insert into sops(code,org_id,title,dept,l1_chain,l2_group,status,version,owner_role,l2_code,l3_no,tools,frequency,evidence,review_due)
select l.code||'.'||s.k, 'ITRAN', s.name, l.dept, l.l1, l.name, 'NHAP', 1, 'team_lead', l.code, s.k, l.tools, 'Theo ca/lịch', l.evidence, current_date + 365
from _l2 l, unnest(l.sops) with ordinality as s(name, k)
on conflict (code) do update set title=excluded.title, dept=excluded.dept, l1_chain=excluded.l1_chain, l2_group=excluded.l2_group, l2_code=excluded.l2_code, l3_no=excluded.l3_no, tools=excluded.tools, evidence=excluded.evidence;
alter table process_steps add column if not exists sop_code text; update process_steps ps set sop_code = ps.process_code||'.'||ps.step_no where ps.process_code like 'SOP-%' and sop_code is null;
-- CCP mẫu (HACCP): đánh dấu SOP có điểm kiểm soát tới hạn
update sops set ccp=true, ccp_limit='Nhiệt phòng ≤12°C; sản phẩm ≤4°C trong 2h', ccp_action='Dừng, kiểm sản phẩm, làm lạnh lại/loại, INCIDENT' where code in ('SOP-CB-01.3','SOP-CB-01.6');
update sops set ccp=true, ccp_limit='Ẩm cuối ≤12% (sấy khô), aw <0,6', ccp_action='Sấy tiếp/loại lô' where code='SOP-CB-03.3';
update sops set ccp=true, ccp_limit='Nhiệt tâm ≥75°C', ccp_action='Nấu tiếp; loại nếu không đạt' where code='SOP-RS-03.4';
update sops set ccp=true, ccp_limit='Kho lạnh ≤4°C liên tục', ccp_action='Chuyển kho dự phòng, đánh giá lô' where code='SOP-CB-06.2';
