update processes p set visible_depts = (select array_agg(distinct x) from (select unnest(coalesce(p.visible_depts,'{}')) as x union select ps.dept_code from process_steps ps where ps.process_code=p.code and ps.dept_code is not null and ps.dept_code<>'*') u) where p.code like 'SOP-%';
